parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "issue_category": {
      "type": "string",
      "enum": [
        "missing_item",
        "wrong_item",
        "damaged_item",
        "delivery_issue",
        "product_quality",
        "other",
        "unknown"
      ]
    },
    "analysis": {
      "type": "string",
      "description": "An English report under 150 words covering the customer claim, relevant database facts, uncertainties, and 1–2 recommended next steps."
    }
  },
  "required": ["issue_category", "analysis"],
  "additionalProperties": false
}
